/**
 * Quality filters for semantic memory indexing (#223).
 * Skip license headers, generated files, minified code, and empty barrels.
 */

export interface QualityResult {
	shouldIndex: boolean;
	reason?: string;
}

/**
 * Determine if a file chunk should be indexed based on quality heuristics.
 */
export function shouldIndexChunk(text: string, filePath: string): QualityResult {
	const trimmed = text.trim();

	if (trimmed.length === 0) {
		return { shouldIndex: false, reason: "empty" };
	}

	if (isLicenseHeader(trimmed)) {
		return { shouldIndex: false, reason: "license header" };
	}

	if (isGeneratedFile(trimmed, filePath)) {
		return { shouldIndex: false, reason: "generated file" };
	}

	if (isMinified(trimmed)) {
		return { shouldIndex: false, reason: "minified" };
	}

	if (isEmptyBarrel(trimmed, filePath)) {
		return { shouldIndex: false, reason: "empty barrel" };
	}

	return { shouldIndex: true };
}

/**
 * Detect license headers (common boilerplate).
 */
function isLicenseHeader(text: string): boolean {
	// Common license markers
	const licenseKeywords = [
		"license",
		"copyright",
		"spdx-license-identifier",
		"licensed under",
		"permission is hereby granted",
		"redistribution and use",
		"all rights reserved",
		"mit license",
		"apache license",
		"gpl",
		"bsd license",
	];

	// Check if it's a comment block starting with license keywords
	const firstLines = text.split("\n").slice(0, 10).join("\n").toLowerCase();

	if (licenseKeywords.some((keyword) => firstLines.includes(keyword))) {
		// Ensure it's mostly a comment block
		const commentLines = text.split("\n").filter((line) => {
			const trimmed = line.trim();
			return (
				trimmed.startsWith("//") ||
				trimmed.startsWith("*") ||
				trimmed.startsWith("/*") ||
				trimmed.startsWith("#") ||
				trimmed.startsWith("--")
			);
		}).length;

		const totalLines = text.split("\n").length;
		if (commentLines > totalLines * 0.7) {
			return true;
		}
	}

	return false;
}

/**
 * Detect generated files (@generated marker or common generated patterns).
 */
function isGeneratedFile(text: string, filePath: string): boolean {
	// Check for @generated marker (common in codegen)
	if (text.includes("@generated") || text.includes("@Generated")) {
		return true;
	}

	// Common generated file patterns
	const generatedPatterns = [
		"This file was automatically generated",
		"This file is auto-generated",
		"DO NOT EDIT",
		"Code generated by",
		"Generated by:",
		"Auto-generated from",
		"Automatically generated by",
	];

	const firstLines = text.split("\n").slice(0, 20).join("\n");
	if (generatedPatterns.some((pattern) => firstLines.includes(pattern))) {
		return true;
	}

	// File name patterns for generated files
	if (
		filePath.includes(".generated.") ||
		filePath.endsWith(".g.ts") ||
		filePath.endsWith(".g.js") ||
		filePath.endsWith("_pb.ts") ||
		filePath.endsWith("_pb.js")
	) {
		return true;
	}

	return false;
}

/**
 * Detect minified code (very long lines with no whitespace).
 */
function isMinified(text: string): boolean {
	const lines = text.split("\n");
	
	// Single line file that's very long with no spaces
	if (lines.length <= 3 && text.length > 100) {
		const spaces = (text.match(/\s/g) || []).length;
		const spaceRatio = spaces / text.length;
		if (spaceRatio < 0.02) {
			return true;
		}
	}
	
	return false;
}

/**
 * Detect empty re-export barrels (files with only export statements).
 */
function isEmptyBarrel(text: string, filePath: string): boolean {
	// Only apply to JS/TS files
	const ext = filePath.slice(filePath.lastIndexOf(".")).toLowerCase();
	if (![".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs"].includes(ext)) {
		return false;
	}

	const lines = text.split("\n");
	const meaningfulLines = lines.filter((line) => {
		const trimmed = line.trim();
		return trimmed.length > 0 && !trimmed.startsWith("//") && !trimmed.startsWith("/*") && !trimmed.startsWith("*");
	});

	// All meaningful lines are exports
	const exportLines = meaningfulLines.filter((line) => {
		const trimmed = line.trim();
		return trimmed.startsWith("export ") || trimmed.startsWith("export{") || trimmed.startsWith("export {");
	});

	// Consider it a barrel if all meaningful lines are exports and there are only a few
	if (meaningfulLines.length > 0 && exportLines.length === meaningfulLines.length && meaningfulLines.length <= 5) {
		return true;
	}

	return false;
}

/**
 * Apply filters to a list of chunks, returning only those that should be indexed.
 */
export function filterChunks<T extends { text: string }>(
	chunks: T[],
	filePath: string,
): Array<T & { filterReason?: string }> {
	return chunks
		.map((chunk) => {
			const result = shouldIndexChunk(chunk.text, filePath);
			if (!result.shouldIndex) {
				return { ...chunk, filterReason: result.reason };
			}
			return chunk;
		})
		.filter((chunk) => !("filterReason" in chunk));
}
